struct Interval{int start;int end;};int insert_interval(struct Interval a[],int n,struct Interval value,struct Interval result[]){int i;int count;i=0;count=0;while(i<n&&a[i].end<value.start)result[count++]=a[i++];while(i<n&&a[i].start<=value.end){if(a[i].start<value.start)value.start=a[i].start;if(a[i].end>value.end)value.end=a[i].end;i=i+1;}result[count++]=value;while(i<n)result[count++]=a[i++];return count;}
int main(void){struct Interval a[2]={{1,3},{6,9}};struct Interval b[5]={{1,2},{3,5},{6,7},{8,10},{12,16}};struct Interval r[8];struct Interval v;int c;v.start=2;v.end=5;c=insert_interval(a,2,v,r);if(c!=2||r[0].start!=1||r[0].end!=5||r[1].start!=6)return 1;v.start=4;v.end=8;c=insert_interval(b,5,v,r);if(c!=3||r[1].start!=3||r[1].end!=10)return 2;return 42;}
